import "../styles/Navbar.css";

function Navbar() {
  return (
    <nav className="navbar">
      <h2>🌊 AquaDetect AI</h2>

      <ul>
        <li><a href="#home">Home</a></li>
        <li><a href="#detect">Detect</a></li>
        <li><a href="#about">About</a></li>
        <li><a href="#contact">Contact</a></li>
      </ul>
    </nav>
  );
}

export default Navbar;
